// pages/site-to-demo.mjs — sections 8 and 10–14: Site · Portals · Settings & operator · States · Decisions · Demo. (9, Approvals and Money, is pages/money.mjs.)
import * as L from '../shell.mjs';
import { hrefFor } from '../files.mjs';
import { urlOf, idOf } from '../patterns.mjs';
import * as S5 from '../patterns.mjs';
import * as TK from '../tokens-candidates.mjs';
import * as T from '../tokens.mjs';
import { ADJUST } from '../adjust.mjs';
const V6 = T.verify();
const g6 = (mode, label) => V6.rows.find(r => r.mode === mode && r.kind === 'contrast' && r.label === label).value.toFixed(2);
const SAFFRON = '#ff9933', INDIA_GREEN = '#138808';
const flagGap = (hex, ref) => TK.dE(TK.oklab(hex.slice(0, 7)), TK.oklab(ref)).toFixed(1);
Object.assign(L.VALUE_LINES, { 'Your preferences › Keyboard': 'Turn off one-key shortcuts if you use speech input or a switch, so a stray letter never moves you somewhere you did not mean to go.' });
import { phead, pnav, todayHero, todayStats } from './today-to-buying.mjs';
import * as PANELS from '../panels.mjs';
import { moneyIn, moneyOut } from '../cards.mjs';
const { emptyFiltered, pager, chips, bulkbar, sortTh, selTh, selTd, fmt, fmtQty, fmtBp, money, td, pill, icon, esc, labelOf2, V2, V2_CLIENT, pt, ct, h6, sample, note, say, tag, frame, shell, card, stat, delta, hero, spark, empty, notice, refuse, unreachable, skeleton, field, moneyField, choice, notes, picker, drawer, gate, tick, tabs, subtabs, illo, projectOf, R, kv } = L;

const ST = ['Daily log', 'Imprest', 'Measurement', 'Recce'];
const siteHead = (title, sub, primary) => `<div class="page-head"><div>${pt(title)}<p class="ps">${sub}</p></div><div class="actions"><button class="btn" type="button">${icon('download')}Export</button><button class="btn primary" type="button">${icon('plus')}${primary}</button></div></div>`;

// ============================================================ 5 --
export function site() {
  const d = L.DAILY; const P = L.PEOPLE;
  const onSite = d.manpower.reduce((n, [, c]) => n + c, 0);
  const reportsByDay = L.SEED.DAILY_REPORTS.filter(r => r.date === L.dayFrom(-1));
  const onSiteAll = reportsByDay.reduce((n, r) => n + r.manpower.reduce((m, x) => m + x.headCount, 0), 0);
  const onSiteBefore = L.SEED.DAILY_REPORTS.filter(r => r.date === L.dayFrom(-2)).reduce((n, r) => n + r.manpower.reduce((m, x) => m + x.headCount, 0), 0);
  const openIssues = L.SEED.ISSUES.filter(i => i.open);
  const sitesOn = L.PROJECTS.filter(p => p.state === 'in_progress' || p.state === 'won').length;
  const daily = siteHead('Site', `daily reports from ${new Set(L.SEED.DAILY_REPORTS.map(r => r.project)).size} sites · none filed today yet · ${reportsByDay.length} yesterday`, 'New daily report') + subtabs(ST, 'Daily log') +
    `<div class="stats">${stat('On site yesterday, all projects', `${onSiteAll}`, { delta: delta(onSiteAll >= onSiteBefore ? 'up' : 'down', `${Math.abs(onSiteAll - onSiteBefore)}`, 'on the day before'), tone: onSiteAll >= onSiteBefore ? 'up' : 'down', series: [0, 1, 2, 3, 4].map(i => L.SEED.DAILY_REPORTS.filter(r => r.date === L.dayFrom(i - 5)).reduce((n, r) => n + r.manpower.reduce((m, x) => m + x.headCount, 0), 0)) })}${stat('Reports filed today', `0<small style="font-size:var(--font-size-heading-small);color:var(--ink-soft);margin-left:var(--space-050)">of ${sitesOn}</small>`, { delta: `<b>${L.SITES_NO_REPORT.names}</b> have never filed one`, tone: 'watch' })}${stat('Open site issues', `${openIssues.length}`, { delta: `<b>${openIssues.filter(i => i.severity === 'blocking').length} blocking</b> · both on ${L.OPEN}`, tone: 'watch' })}</div>
<div data-hero>${card(`${esc(d.date)} — ${L.OPEN}`, `<div class="daysum"><div><b>${onSite}</b>on site<small>${d.manpower.map(([t, c]) => `${c} ${t.toLowerCase()}`).join(' · ')}</small></div><div><b>${d.manpower.length}</b>floors<small>filed by ${esc(d.by)}</small></div><div><b>${d.issues.length}</b>issues open<small>one blocking</small></div><div><b>0</b>photos<small>none attached</small></div></div>
<div class="card-b">${h6('Notes', 'ct')}<p style="margin:var(--space-100) 0 0">${esc(d.notes)}</p></div>
<div class="card-b continued">${h6('Issues on this site', 'ct')}<ul class="checks" style="margin:var(--space-100) calc(var(--space-250) * -1) 0">${d.issues.map((w, i) => `<li>${tick(false)}<div>${esc(w)}</div>${i === 0 ? `<a href="#" class="btn sm">Open the issue</a>` : '<span></span>'}</li>`).join('')}</ul></div>`, { sub: `${esc(d.site)}`, actions: `<div class="actions"><a href="#" class="btn">${icon('download')}PDF</a></div>` })}</div>
${card('Recent reports', `<div class="tbl-wrap"><table class="tbl"><thead><tr><th class="num" aria-sort="descending">Day${icon('sort', 'i sm')}</th><th>Site</th><th class="num">On site</th><th class="num">Issues open</th><th></th></tr></thead><tbody>${L.DAILY_LIST.map(([day, s, n, w, i]) => `<tr class="row-link"><td class="num">${day}</td><td>${s}</td><td class="num">${n}</td><td class="num">${i ? `<span class="stock-low">${i}</span>` : '0'}</td><td><a href="#">Open</a></td></tr>`).join('')}</tbody></table></div>${pager({ from: 1, to: L.DAILY_LIST.length, total: L.SEED.DAILY_REPORTS.length, page: 1, pages: Math.ceil(L.SEED.DAILY_REPORTS.length / L.DAILY_LIST.length), unit: 'reports' })}`)}`;
  // imprest — NOT SEEDED: the design's demonstration ledger on ANU-01 (shell.mjs says so)
  const im = L.IMPREST;
  let running = BigInt(im.balance);
  const ledger = im.rows.map(r => { const row = `<tr class="${r.in ? 'in' : 'out'}"><td class="num">${r.on}</td><td>${esc(r.what)}<span class="sub">${esc(r.who)}${r.receipt ? ' · receipt attached' : ' · <span class="stock-low">no receipt</span>'}</span></td>${r.in ? `<td class="num">${moneyIn(r.in)}</td>` : '<td class="num absent">—</td>'}${r.out ? `<td class="num">${moneyOut(r.out)}</td>` : '<td class="num absent">—</td>'}<td class="num">${fmt(String(running))}</td></tr>`; running = r.in ? running - BigInt(r.in) : running + BigInt(r.out); return row; }).join('');
  const spent = L.add(...im.rows.filter(r => r.out).map(r => r.out));
  const imprest = siteHead('Site', `imprest — site cash at ${im.site}, held by ${esc(im.holder)}`, 'Record an expense') + subtabs(ST, 'Imprest') +
    `<div data-hero>${hero({ eyebrow: `Cash in hand · ${im.site}`, value: fmt(im.balance), text: `of a ${fmt(im.float)} float. ${fmt(spent)} spent this week across ${im.rows.filter(r => r.out).length} expenses; one has no receipt yet. Below ${fmt(L.R(20_000))} the site asks head office for a top-up.`, delta: delta('down', fmt(spent), 'this week'), tone: 'down', series: L.SPARK.imprest, thr: L.IMPREST.float, actions: `<button class="btn primary" type="button">${icon('plus')}Record an expense</button><button class="btn" type="button">Ask for a top-up</button>`, foot: `<span class="who"><span class="avatar">${esc(P.finance.initials[0])}</span><span><b>${esc(P.finance.name)}</b> approves top-ups</span></span>` })}</div>
${card('Ledger', `<div class="tbl-wrap"><table class="tbl ledger"><thead><tr><th class="num">Day</th><th>What</th><th class="num">In</th><th class="num">Out</th><th class="num">Balance</th></tr></thead><tbody>${ledger}</tbody></table></div>${pager({ from: 1, to: L.IMPREST.rows.length, total: L.IMPREST.rows.length, page: 1, pages: 1, unit: 'entries' })}`, { sub: 'this week · every line has a person on it' })}`;
  // measurement
  const measure = measurementScreen();
  // recce — NOT SEEDED: a survey on a seeded lead, the design's facts
  const rc = L.RECCE;
  const recce = siteHead('Site', 'recce — site surveys before a proposal', 'New recce') + subtabs(ST, 'Recce') +
    `<div class="recce"><div data-hero>${card(`${esc(rc.lead)} — ${esc(rc.title)}`, `<div class="card-b"><dl class="kv">${rc.facts.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p style="margin-top:var(--space-200);color:var(--ink-soft)">${esc(rc.notes)}</p></div><div class="photos">${['East bay, columns', 'Raised floor', 'Ceiling void', 'Service lift'].map(p => `<div><span>${esc(p)}</span></div>`).join('')}</div>`, { sub: `${esc(rc.city)} · ${esc(rc.when)} · ${esc(rc.by)}`, actions: `<div class="actions"><a href="#" class="btn">Open lead</a><button class="btn primary" type="button">Start the BOQ</button></div>` })}</div>
${card('Checklist', `<ul class="checks">${rc.checks.map(([t, s, done]) => `<li class="${done ? 'done' : ''}">${tick(done)}<div>${esc(t)}<small>${esc(s)}</small></div><span></span></li>`).join('')}</ul>`, { sub: `${rc.checks.filter(c => c[2]).length} of ${rc.checks.length} done` })}</div>`;
  return `<p class="lede">Site is four tabs on one nav item: the daily log filed from a phone, the imprest ledger, the measurement sheet that every RA bill is raised from, and the recce that starts a proposal. The seed files a report a day for five days on four sites, by the finance login — it has no site engineer, and no imprest, measurement or recce at all; those three screens are drawn on the seed’s names with the design’s own figures, and say so.</p>
${sample(`Site › Daily log — yesterday’s report from ${L.OPEN}`, shell(daily, { current: '/site', label: 'Site · Daily log', who: P.finance.first, role: P.finance.role, scope: L.OPEN, url: urlOf('/site-reports', L.OPEN) }), '', 'daily')}
${sample('Site › Imprest — the site cash ledger', shell(imprest, { current: '/site', label: 'Site · Imprest', who: P.proc.first, role: P.proc.role, scope: L.OPEN, url: urlOf('/site-controls', L.OPEN) }), tag('Not seeded — the design’s ledger on the seed’s names'), 'imprest')}
${note('<p>Imprest is site petty cash, not a statutory computation, so its figures are shown — the CA-gated surfaces are TDS, payments, billing and retention. A line without a receipt says so in words; it is not hidden and not a zero.</p>')}
${sample('Site › Measurement — the sheet behind RA bill 03', shell(measure, { current: '/site', label: 'Site · Measurement', who: P.proc.first, role: P.proc.role, scope: L.OPEN, url: urlOf('/site-controls', L.OPEN) }), tag('Not seeded — contract quantities are the seed’s BOQ, the claims are the design’s'), 'measure')}
${note('<p>A measurement sheet is quantities, never money: the RA bill applies the contract rates to it. Measured beyond the contract quantity is shown in the error colour and blocks the bill until a variation covers it. The seed has no quantity surveyor; procurement plays the sheet here.</p>')}
${sample('Site › Recce — the survey that starts a proposal', shell(recce, { current: '/site', label: 'Site · Recce', who: P.admin.first, role: P.admin.role }), tag('Not seeded — a survey on a seeded lead'), 'recce')}
${note('<p>A recce belongs to a lead, so it is reachable from Sales too; it lives under Site because the people who do it are the site team. Its quantities seed the proposal BOQ.</p>')}`;
}
// ============================================================ 7 --
export function portals() {
  const P = L.PEOPLE; const vendor = L.V.Prakashvahini; const firm = L.TENANT.short;
  const orderCard = (o) => `<li class="card"><div class="top"><div><b>${o.number}</b><small>raised ${o.raised} · ${esc(firm)}</small></div>${labelOf2(V2.po, o.state)}</div><div class="amt">${money(o.taxable)}<small>before GST · GST ${fmt(o.gst)} · total ${fmt(o.gross)}</small></div>${o.acceptance === null ? `<div class="row"><button class="btn primary lg" type="button">${icon('check')}Accept</button><button class="btn lg" type="button">${icon('x')}Decline</button></div>` : `<div class="row">${labelOf2(V2.acceptance, o.acceptance)}<a href="#" class="btn ghost">See lines</a></div>`}</li>`;
  const PN = [['Orders', 'inbox'], ['Bills', 'bill'], ['Payments', 'rupee'], ['Documents', 'doc']];
  const vhead = (sub) => phead(vendor.short, sub, '', { who: P.vendorPortal.name });
  const orders = `${vhead(`Orders from ${firm}`)}<div class="p-body">${pt('Your orders')}<p class="ps">${L.VP_ORDERS.filter(o => o.acceptance === null).length} needs your answer</p><div data-hero><ul class="card-list" style="list-style:none;margin:0;padding:0">${L.VP_ORDERS.map(orderCard).join('')}</ul></div></div>${pnav(PN, 'Orders')}`;
  const billPill = (b) => b.state === 'paid' ? pill('ok', 'Paid') : labelOf2(V2.bill, b.state);
  const bills = `${vhead(firm)}<div class="p-body">${pt('Your bills')}<p class="ps">${L.VP_BILLS.length} sent this quarter</p>
<div data-hero><ul class="card-list" style="list-style:none;margin:0;padding:0">${L.VP_BILLS.map(b => `<li class="card"><div class="top"><div><b>${b.billNumber}</b><small>sent ${b.submitted} · ${b.order}</small></div>${billPill(b)}</div><div class="amt">${money(b.amount)}<small>what you billed · ${b.paidOn ? `paid ${b.paidOn}` : `due ${b.dueOn}`}</small></div>${b.covering ? `<p>${esc(b.covering)}</p>` : ''}<div class="u-hold"></div></li>`).join('')}</ul></div>
</div>${pnav(PN, 'Bills')}`;
  const sendBill = `${vhead(firm)}<div class="p-body">${pt('Send a bill')}<p class="ps">against an accepted order</p><div data-hero>${card(null, `<div class="card-b"><form onsubmit="return false">${choice('vp-order', 'For order', L.VP_ORDERS.filter(o => o.acceptance === 'accepted').map(o => [o.number, o.number]), 'PO-ANU-MEP-01')}${field('vp-bill', 'Your bill number', { value: 'PEC-RA-03', required: true })}${moneyField('vp-amt', 'Amount', '', 'Rupees, up to two decimals.', true)}<div class="stats n2" style="margin:0"><div class="field"><label for="vp-from">From</label><input id="vp-from" type="date" value="2026-09-01"></div><div class="field"><label for="vp-to">To</label><input id="vp-to" type="date" value="2026-09-30"></div></div>${notes('vp-narr', 'What this bill covers', 2)}<div class="actions"><button class="btn primary lg" type="submit" style="width:100%">Send bill</button></div></form></div>`)}</div></div>${pnav(PN, 'Bills')}`;
  // Payments, as shipped: what reached the vendor, what was deducted and under which section, what was held.
  // A vendor sees the tax taken from their own money — they reconcile it against Form 26AS — and a provisional
  // rate says so in the neutral pill, because the vendor audience is shown no caution tone (13 · Decisions).
  const VP_PAY = L.SEED.PAYMENTS.filter(p => p.vendor === vendor.key && p.kind === 'bill');
  const payments = `${vhead(firm)}<div class="p-body">${pt('Payments')}<p class="ps">what reached you, and what was held back</p><div data-hero><ul class="card-list" style="list-style:none;margin:0;padding:0">${VP_PAY.map(p => `<li class="card"><div class="top"><div><b>${p.bill}</b><small>${p.on} · ${p.reference}</small></div>${pill('ok', 'Paid')}</div><div class="amt">${money(p.net)}<small>reached you</small></div><div class="card-b tight"><dl class="kv"><dt>Billed</dt><dd>${fmt(p.gross)}</dd><dt>Tax deducted</dt><dd>${fmt(p.tds)} · ${p.section} at ${p.rateBp / 100}% ${pill('idle', 'Provisional')}</dd><dt>Retention withheld</dt><dd>${fmt(p.retention)}</dd></dl></div></li>`).join('')}</ul></div>
${pager({ from: 1, to: VP_PAY.length, total: VP_PAY.length, page: 1, pages: 1, unit: 'payments' })}</div>${pnav(PN, 'Payments')}`;
  // client portal — Elizabeth Kuriakose at Anuvanshik, linked to ANU-01
  const proj = L.OPEN_PROJECT;
  const achieved = L.MILESTONES.filter(m => m.status === 'achieved').reduce((s, m) => s + m.shareBp, 0);
  const ms = L.MILESTONES.map(m => `<li class="${m.status === 'achieved' ? 'done' : m.status === 'in_progress' ? 'now' : ''}">${tick(m.status === 'achieved')}<div><b>${esc(m.name)}</b><small>${esc(m.trigger)}${m.on ? ` · ${m.on}` : m.status === 'in_progress' ? ' · next' : ''}</small></div><div class="num">${fmtBp(m.shareBp)}<small>of contract</small></div></li>`).join('');
  const pending = L.VARIATIONS.filter(v => v.state === 'pending_client'); const decided = L.VARIATIONS.filter(v => v.state === 'client_approved' || v.state === 'client_rejected');
  const invoices = L.SEED.INVOICES.filter(i => i.project === proj.code);
  const invoiced = L.add(...invoices.map(i => i.total)), paid = L.add(...invoices.map(i => i.received)), due = L.add(...invoices.map(i => i.balance));
  const chead = (cur) => phead(proj.clientShort, `${esc(proj.name)} · by ${firm}`, `<nav class="ptabs" aria-label="Project">${['Progress', 'Variations', 'Documents', 'Billing'].map(t => `<a href="#" ${t === cur ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>`, { app: 'client', who: P.clientPortal.name });
  const content = `${chead('Progress')}<div class="p-body">
<div class="page-head"><div>${pt('Progress')}<p class="ps">Week 38 · ${L.SEED.DAILY_REPORTS.filter(r => r.project === proj.code).length} site reports this fortnight</p></div></div>
<div data-hero>${hero({ eyebrow: 'Milestones reached', value: `${achieved / 100}`, unit: '%', text: `of the contract — none of the four stages is marked reached yet; <b>${esc(L.MILESTONES[0].name)}</b> is next, and releases ${fmtBp(L.MILESTONES[0].shareBp)}.`, actions: '' })}</div>
${card('Milestones', `<ul class="mstones">${ms}</ul>`, { sub: `${fmtBp(achieved)} reached` })}
${card('Needs your sign-off', pending.map(v => `<div class="variation"><div class="vh"><b>${v.number} — ${esc(v.title)}</b>${labelOf2(V2_CLIENT.co, v.state)}</div><div class="num">${fmt(v.impact)}<small>${v.impact.startsWith('-') ? 'a credit — your contract value goes down by this' : 'added to your contract value'}</small></div><form style="margin-top:var(--space-150)" onsubmit="return false">${field(`sign-${v.number}`, 'Your name, as on the agreement', { placeholder: P.clientPortal.name })}<div class="actions"><button class="btn primary lg" type="submit">${icon('pen')}Approve ${v.number}</button><button class="btn lg" type="button">Decline</button></div><p class="muted" style="margin-top:var(--space-100);font-size:var(--font-size-body-small)">A decision is final — it goes straight into the contract value.</p></form></div>`).join(''), { sub: `${pending.length} variation` })}
${card('Decided', `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Variation</th><th class="num">Amount</th><th>Decision</th><th class="num">When</th></tr></thead><tbody>${decided.map(v => `<tr><td>${v.number}<span class="sub">${esc(v.title)}</span></td>${td(v.impact)}<td>${labelOf2(V2_CLIENT.co, v.state)}</td><td class="num">${v.on}</td></tr>`).join('')}</tbody></table></div>${pager({ from: 1, to: decided.length, total: decided.length, page: 1, pages: 1, unit: 'decided' })}`)}
${card('Documents', `<ul class="docs">${L.DOCS.map(([n, m, d]) => `<li>${icon('doc')}<div><b>${esc(n)}</b><small>${esc(m)} · ${d}</small></div><a href="#" class="btn">${icon('download')}Download</a></li>`).join('')}</ul>`)}
${card('Billing', `<div class="card-b">${kv([['Invoiced', `${fmt(invoiced)} <span class="muted">with GST</span>`], ['Paid', `${fmt(paid)} <span class="muted">received by your contractor</span>`], ['Due', `${fmt(due)} <span class="muted">still to pay</span>`]])}</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Invoice</th><th class="num">Invoiced</th><th class="num">Paid</th><th class="num">Due</th></tr></thead><tbody>${invoices.map(i => `<tr><td>${i.number}<span class="sub">${i.invoiceDate} · IGST ${fmt(i.igst)} ${pill('warn', 'Provisional')}</span></td><td class="num">${fmt(i.total)}</td><td class="num">${fmt(i.received)}</td><td class="num">${fmt(i.balance)}</td></tr>`).join('')}</tbody></table></div><p class="skel-note muted">Draft: provisional rates — the GST rate is still to be confirmed.</p>`, { sub: `invoices from ${firm}, with what you have paid` })}
</div>`;
  return `<p class="lede">A subcontractor on a phone at a site; a building owner on a tablet between meetings. Neither sees an internal code. A deduction figure appears in one place only — the tax taken from a vendor’s own payment, which the vendor reconciles against Form 26AS. The two logins are the seed’s: ${esc(P.vendorPortal.name)} at ${esc(vendor.short)}, and ${esc(P.clientPortal.name)} at ${esc(proj.clientShort)}, linked to ${proj.code}.</p>
${sample('Vendor portal — Orders · Bills · Send a bill · Payments', `<div class="dsx-grid phones">${frame(orders, 'phone', 'Orders', 'vendor portal')}${frame(bills, 'phone', 'Bills', 'vendor portal')}${frame(sendBill, 'phone', 'Send a bill', 'vendor portal')}${frame(payments, 'phone', 'Payments', 'vendor portal')}</div>`)}
${note('<p>A bill that was sent back says why, in the words the finance person typed, with one button to fix it — no bill on the seed has been sent back, so the state is drawn on part 12. Every control is at least 46px tall and every input 16px, so a phone keyboard does not zoom. The vendor signs in with a link — no app, no password.</p>')}
${sample('Client portal — progress, variations, documents and billing', frame(content, 'tablet', 'Progress', 'client portal'))}
${note(`<p>${decided[0].number} is the credit: <code>${fmt(decided[0].impact)}</code>, sign outside the symbol, same ink, and the sentence underneath says what it means. Drafts are never shown to a client — CO-02, at nil effect and not sent, is not here.</p>`)}`;
}
// ============================================================ 8 --
// Settings — all thirteen pages in one place (19 September 2026, the layout the buyers know): a category list on
// the left, and on the right one grouped table with a count badge on each group and a star to favourite a row.
