const STARRED = new Set(['Tax', 'Approval steps']);
// the settings hub (19 September): the gear opens it — every page as a card, grouped, with one line each; each card
// wears its category's tinted disc with the category's duotone icon (the firm blue, people purple, how work moves
// teal, the record neutral, yours green)
function settingsHub() {
  const total = SETTINGS_GROUPS.reduce((n, [, pages]) => n + pages.length, 0);
  const groups = SETTINGS_GROUPS.map(([g, pages]) => `<section class="hub-group" aria-label="${esc(g)}"><h2 class="hub-h">${esc(g)}<span class="badge">${pages.length}</span></h2><div class="hub-grid">${pages.map(([name, href, what, mark]) => `<a class="hub-card" href="#" data-href="${href}"><span class="disc ${L.HUB_DISC[g][0]}" aria-hidden="true">${L.duo(L.HUB_DISC[g][1])}</span><span class="hub-body"><b>${esc(name)}${mark === 'new' ? ' ' + pill('active', 'new') : ''}</b><small>${esc(what)}</small></span></a>`).join('')}</div></section>`).join('');
  return S5.pageHead({ title: 'Settings', sub: `${total} pages — the firm’s, and yours · opened from the gear` }) + `<div data-hero>${groups}</div>`;
}
// Settings › Terminology (new, 19 September): the words this firm uses, one choice per pair, read by every label
function terminology() {
  const PAIRS = [['boq', 'The priced list of work', ['BOQ', 'Estimate'], 0, 'Bill of quantities is what Indian contractors and PWD-trained engineers say; Estimate is what a design-led firm says to a client.'], ['variation', 'A change to the contract', ['Variation', 'Change order'], 0, 'Variation is the Indian and British word; Change order is the American one some clients bring.'], ['daily', 'What site files each day', ['Daily report', 'Site diary'], 0, ''], ['vendor', 'Who you buy from', ['Vendor', 'Supplier'], 0, '']];
  const pair = ([id, what, [a, b], picked, why]) => `<div class="term-row" role="radiogroup" aria-labelledby="term-${id}"><p class="term-l" id="term-${id}">${esc(what)}</p><div class="term-opts">${[a, b].map((o, i) => `<label class="radio"><span class="ico"><input type="radio" name="${id}" ${i === picked ? 'checked' : ''}></span><span>${esc(o)}</span></label>`).join('')}</div>${why ? `<p class="hint">${esc(why)}</p>` : ''}</div>`;
  return `<div class="page-head"><div><p class="crumb"><a href="#">Settings</a> › Terminology</p>${pt('Terminology')}<p class="ps">The words this firm uses. Every label, column, menu and document reads the choice here; nothing else changes.</p></div></div>
<div data-hero>${card('Four pairs', `<div class="card-b"><form onsubmit="return false">${PAIRS.map(pair).join('')}<div class="actions"><button class="btn primary" type="submit">Save</button><button class="btn ghost" type="button">Cancel</button></div></form></div>`, { sub: 'one choice each · the sidebar, the lists and the PDFs follow', actions: tag('new — no such setting exists') })}</div>
${notice('info', 'What a choice changes', 'The sidebar entry, the list title, every column and button that names the thing, and the heading on the PDF. The route stays /boq whichever word is chosen, so a link never breaks.')}`;
}
