const REPORT_GROUPS = [
  ['Money', [['Receivables ageing', 'What each client owes, by how long it has been owed', true], ['Payables ageing', 'What is owed to each vendor, by age', true], ['Cash flow', 'In and out by month, against the bank', false], ['Tax deducted', 'Every deduction this quarter, for the 26Q', true], ['GST summary', 'Output and input tax by month', false]]],
  ['Buying', [['Orders by vendor', 'What was ordered from whom, and at what rate against the agreed one', false], ['Agreed rates ending', 'Rate contracts that expire within 90 days', false], ['Stock on hand', 'Every store, every item, its value', false]]],
  ['Projects', [['Contract against ordered against billed', 'Every project’s three numbers on one page', true], ['Margin at risk', 'Orders past their package budget, by project', false], ['Variations', 'Open and agreed, by project', false]]],
  ['Site', [['Daily reports filed', 'Sites with and without a report, by day', false], ['Site cash', 'Imprest issued, spent and in hand, by site', false]]],
  ['Sales', [['Pipeline', 'Leads by stage and expected value', false], ['Won and lost', 'By quarter, with the reason', false]]],
];
function reportsCenter() {
  const all = REPORT_GROUPS.flatMap(([g, rs]) => rs.map(r => [g, ...r]));
  const favs = all.filter(r => r[3]);
  const cats = `<nav class="cat-list" aria-label="Categories"><ul><li><a href="#" aria-current="true">${icon('star', 'i sm')}Favourites<span class="badge">${favs.length}</span></a></li>${REPORT_GROUPS.map(([g, rs]) => `<li><a href="#">${esc(g)}<span class="badge">${rs.length}</span></a></li>`).join('')}</ul></nav>`;
  const star = (name, on) => `<button class="btn icon ghost sm star${on ? ' on' : ''}" type="button" aria-pressed="${on}" aria-label="${on ? `Unfavourite ${esc(name)}` : `Favourite ${esc(name)}`}">${icon('star', 'i sm')}</button>`;
  const rows = REPORT_GROUPS.map(([g, rs]) => `<tr class="grp"><th colspan="2" scope="rowgroup">${esc(g)}<span class="badge">${rs.length}</span></th></tr>`
    + rs.map(([name, what, on]) => `<tr><td><a href="#">${esc(name)}</a><span class="sub">${esc(what)}</span></td><td class="star-c">${star(name, on)}</td></tr>`).join('')).join('');
  return S5.pageHead({ title: 'Reports', sub: `${all.length} reports in ${REPORT_GROUPS.length} groups · ${favs.length} favourited`, primary: `<button class="btn primary" type="button">${icon('download')}Export the last run</button>` })
    + `<div class="settings-grid">${cats}<div data-hero><section class="card settings-tbl" aria-label="All reports"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Report</th><th class="star-c"><span class="sr-only">Favourite</span></th></tr></thead><tbody>${rows}</tbody></table></div></section></div></div>`;
}
