  const SHORTCUTS = [['<kbd>/</kbd>', 'Go to search, scoped to the page', true], ['<kbd>Shift</kbd>+<kbd>?</kbd>', 'Show every shortcut', true], ['<kbd>N</kbd>', 'The primary action on this page', true], ['<kbd>C</kbd>, then a key', 'Quick-create: <kbd>O</kbd> an order, <kbd>B</kbd> a bill, <kbd>P</kbd> a project', true], ['<kbd>P</kbd>', 'Open the project switcher', true], ['<kbd>Esc</kbd>', 'Close the top-most thing — a pane, a panel, a filter', false], ['<kbd>↑</kbd> <kbd>↓</kbd> · <kbd>Enter</kbd>', 'Move through a table and open a row, once the table has focus', false], ['<kbd>Ctrl</kbd>+<kbd>A</kbd>', 'Select every row on the page', false]];
  const shortcutRows = (on) => SHORTCUTS.map(([k, what, single]) => `<tr><td class="nowrap">${k}</td><td>${what}</td><td>${single ? (on ? pill('ok', 'On') : pill('idle', 'Off')) : '<span class="muted">Always — not a single character</span>'}</td></tr>`).join('');
